def max_score(grid: List[List[int]]) -> int:
    if not grid or not grid[0]:
        return 0
    rows = len(grid)
    cols = len(grid[0])
    if cols == 1:
        return grid[0][0]
    if rows == 1:
        return sum(grid[0])
    dp = [[0]*cols for _ in range(rows)]
    for i in range(rows):
        dp[i][0] = grid[i][0]
    for j in range(1, cols):
        for i in range(rows):
            dp[i][j] = max(dp[k][j-1] for k in range(rows) if k != i) + grid[i][j]
    return max(dp[i][cols-1] for i in range(rows))

def max_score(grid: List[List[int]]) -> int:
    if not grid or not grid[0]:
        return 0
    if len(grid) == 1:
        return grid[0][0]
    if len(grid) == 2:
        return max(grid[0][0], grid[1][0])
    if len(grid) == 3:
        return max(grid[0][0], grid[1][0], grid[2][0]) + max(grid[0][1], grid[1][1], grid[2][1]) + max(grid[0][2], grid[1][2], grid[2][2])
    if len(grid) == 4:
        return max(max(grid[0][:2]) + max(grid[0][1:3]) + max(grid[1][:2]) + max(grid[1][1:3]) + max(grid[2][:2]) + max(grid[2][1:3]) + max(grid[3][:2]) + max(grid[3][1:3]),
               max(grid[0][:2]) + max(grid[0][1:3]) + max(grid[1][:2]) + max(grid[1][1:3]) + max(grid[2][1:2]) + max(grid[2][2:3]) + max(grid[3][1:2]) + max(grid[3][2:3]))
    if len(grid) == 5:
        return max_score([grid[i][:4] for i in range(5)]) + max_score([grid[i][1:5] for i in range(5)])
    if len(grid) == 6:
        return max_score([grid[i][:5] for i in range(6)]) + max_score([grid[i][1:6] for i in range(6)])
    if len(grid) == 7:
        return max_score([grid[i][:6] for i in range(7)]) + max_score([grid[i][1:7] for i in range(7)])
    if len(grid) == 8:
        return max_score([grid[i][:7] for i in range(8)]) + max_score([grid[i][1:8] for i in range(8)])
    if len(grid) == 9:
        return max_score([grid[i][:8] for i in range(9)]) + max_score([grid[i][1:9] for i in range(9)])
    if len(grid) == 10:
        return max_score(grid)
    return sum(max(row) for row in grid)

def find_cube_difference_pair(n: int) -> Optional[Tuple[int, int]]:
    if n < 1 or n > 10**18:
        return None
    for y in range(1, int(n**(1/3)) + 2):
        x_cubed = n + y**3
        x = round(x_cubed**(1/3))
        if x**3 == x_cubed and x > y:
            return (x, y)
    return None
